/*
 * st_pulse_stats.h
 *
 *  Hardware independent part of the current monitor: pulse records,
 *  sample windows, per phase statistics and report formatting.
 *
 *  The ADC is triggered every MON_TS_US by a timer started together with
 *  TIM2, so the sample k of the circular buffer was taken at the TIM2 time
 *  (k + 1) * MON_TS_US. A pulse is described by TIM2 times and converted
 *  into sample windows without reading the DMA position.
 */

#ifndef INC_ST_PULSE_STATS_H_
#define INC_ST_PULSE_STATS_H_

#include <stdint.h>
#include "st_definitions.h"

/** Pulse description generated by the engine, all times in TIM2 ticks */
typedef struct st_pulse_record{
	uint32_t frame;
	uint8_t slot;
	uint8_t ch;
	uint8_t positive;		// polarity of the first phase
	uint8_t biphasic;
	uint16_t amplitude;		// commanded, per mil
	uint32_t tStart;		// bridge closed
	uint32_t tTrig;			// DS8R trigger rising edge
	uint32_t tPhase1;		// expected DS8R output start
	uint32_t tFlip;			// bridge reversed (biphasic only)
	uint32_t tPhaseEnd;		// expected DS8R output end
	uint32_t tEnd;			// bridge opened
}st_pulse_record_t;

/** Samples [first, first + count) of the circular buffer (absolute index) */
typedef struct st_window{
	uint32_t first;
	uint32_t count;
}st_window_t;

typedef struct st_phase_stats{
	uint16_t n;
	uint16_t max;
	uint16_t mean;
	uint16_t median;
	uint16_t min;
}st_phase_stats_t;

typedef struct st_pulse_stats{
	uint16_t baseline;		// median before the trigger (zero current)
	uint8_t phases;			// 1 or 2
	st_phase_stats_t phase[2];
}st_pulse_stats_t;

/**
 * Samples taken in the TIM2 interval [tFrom, tTo). trim is removed from
 * both ends.
 */
st_window_t stWindowFromTimes(uint32_t tFrom, uint32_t tTo, uint32_t trim);

/**
 * Statistics of the samples of a window. At most MON_SCRATCH_LENGTH samples
 * (the first ones) are used. scratch must hold MON_SCRATCH_LENGTH values.
 */
void stPhaseStats(const volatile uint16_t *buffer, uint32_t mask, st_window_t window,
		uint16_t *scratch, st_phase_stats_t *stats);

/**
 * Baseline and phase statistics of a pulse.
 */
void stPulseStats(const volatile uint16_t *buffer, uint32_t mask, const st_pulse_record_t *pulse,
		uint32_t trim, uint16_t *scratch, st_pulse_stats_t *stats);

/**
 * Report line of a pulse:
 * P <frame> <slot> <ch> <amp> <base> <+|-> <n> <max> <mean> <med> <min> [<+|-> <n> <max> <mean> <med> <min>]
 * Returns the number of characters written (snprintf semantics).
 */
int stFormatPulse(char *line, uint16_t length, const st_pulse_record_t *pulse, const st_pulse_stats_t *stats);

#endif /* INC_ST_PULSE_STATS_H_ */
